def priority(task, state, k=0.5, m=2.0, type_map=1.0, type_reduce=1.0, type_join=1.0):
    est = max(task.estimated_runtime, 1e-6)
    slack = max(0.0, task.due - est - state.now)
    tier = m if task.tenant == 'premium' else 1.0
    if task.task_type == 'map':
        tb = type_map
    elif task.task_type == 'reduce':
        tb = type_reduce
    elif task.task_type == 'join':
        tb = type_join
    else:
        tb = 1.0
    return tier * tb * task.weight / est * math.exp(-slack / (k * max(state.mean_est, 1e-6)))  # tuned (k=0.421,m=1.58,type_map=1.41,type_reduce=1.61,type_join=1.18)

def priority(task, state, k=1.0, m=2.0, s=0.5):
    slack = max(0.0, task.due - task.estimated_runtime - state.now)
    tier = m if task.tenant == 'premium' else 1.0
    atc = task.weight / max(task.estimated_runtime, 1e-6) * math.exp(-slack / (k * max(state.mean_est, 1e-6)))
    lateness_risk = 1.0 / (1.0 + s * slack / max(task.estimated_runtime, 1e-6))
    return tier * atc * lateness_risk  # tuned (k=0.86,m=2.14,s=0.26)
